ReplacementContent:
.hl{padding:2px 4px;border-radius:5px;cursor:pointer;border-bottom:3px solid var(--ink);transition:.15s}
.hl.a{background:var(--pink)}.hl.b{background:var(--sky)}.hl.c{background:var(--lav)}
.hl.off{background:none;border-color:transparent}.hl:hover{transform:translateY(-2px)}
.doc{font:16px/1.8 Georgia,serif;max-height:480px;overflow-y:auto;white-space:pre-wrap;word-break:break-word}
.doc::-webkit-scrollbar{width:6px}.doc::-webkit-scrollbar-thumb{background:var(--ink);border-radius:4px}
.srcs .s{border:2.5px solid var(--ink);border-radius:16px;padding:12px;margin-bottom:10px;transition:.2s;cursor:pointer}
.srcs .s.on{transform:translateX(6px) rotate(-.8deg);box-shadow:4px 4px 0 var(--ink)}
.srcs .s.a{background:var(--pink)}.srcs .s.b{background:var(--sky)}.srcs .s.c{background:var(--lav)}
.srcs .s.dim{opacity:.35}
.hist{display:flex;align-items:center;gap:14px;padding:14px 0;border-top:2px dashed var(--ink);cursor:pointer;flex-wrap:wrap}
.hist:hover b{background:var(--acid)}
.sc{font:800 22px var(--d);min-width:64px;text-align:center;border:2.5px solid var(--ink);border-radius:14px;padding:4px 8px}
.step{display:inline-flex;gap:8px;align-items:center;font:700 12px var(--m);text-transform:uppercase;margin-right:14px}
.step i{width:22px;height:22px;border-radius:50%;border:2px solid var(--ink);display:grid;place-items:center;font-style:normal;background:#fff}
.step.on i{background:var(--acid)}
.doc-box{display:flex;flex-direction:column;gap:8px}
.doc-header{display:flex;align-items:center;justify-content:space-between;padding-bottom:6px;border-bottom:2px dashed var(--ink)}
.insight-card{background:var(--card);border:2.5px solid var(--ink);border-radius:20px;padding:16px;margin:18px 0;box-shadow:4px 4px 0 var(--ink)}
.matrix-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:14px;margin-top:14px}
.matrix-card{background:var(--card);border:2.5px solid var(--ink);border-radius:18px;padding:14px;cursor:pointer;transition:.15s;box-shadow:3px 3px 0 var(--ink)}
.matrix-card:hover{transform:translate(-2px,-2px);box-shadow:5px 5px 0 var(--ink)}
.badge-v{background:var(--pink);color:var(--ink);padding:2px 8px;border-radius:99px;font:700 11px var(--m);border:1.5px solid var(--ink);display:inline-block}
.badge-p{background:var(--sky);color:var(--ink);padding:2px 8px;border-radius:99px;font:700 11px var(--m);border:1.5px solid var(--ink);display:inline-block}

